using System;
using System.IO;
using System.Linq;
using TasiaCraft;
public static partial class MediaBinTest {
 static bool MoveNear(double a,double b){return Math.Abs(a-b)<1e-6;}
 static void MoveCase(double start,double span,double delta,double target,double expected,string edge,string label){var result=TimelineSnapping.Move(start,span,delta,new[]{target},100,false);Check(MoveNear(result.Delta,expected)&&result.Target==target&&result.Edge==edge,label);}
 static void MoveSnapTests(Editor editor,Project original,LivePreview preview){
  MoveCase(1,2,2.96,4,3,"start","leading edge snaps while moving right");MoveCase(4,2,-2.96,1,-3,"start","leading edge snaps while moving left");MoveCase(1,2,.96,4,1,"end","trailing edge snaps while moving right");MoveCase(4,2,-3.96,2,-4,"end","trailing edge snaps while moving left");MoveCase(1,2,1,4,1,"end","already aligned trailing edge keeps zero correction");MoveCase(4,2,-4,0,-4,"start","leading edge can snap to zero boundary");MoveCase(1,200,.96,202,1,"end","long selection span uses its trailing bound");
  var result=TimelineSnapping.Move(0,2,1.04,new[]{1.1,3.05},100,false);Check(MoveNear(result.Delta,1.05)&&result.Edge=="end","nearest correction wins across both endpoints");result=TimelineSnapping.Move(0,2,1,new[]{1.0625,2.9375},100,false);Check(result.Delta==1.0625&&result.Edge=="start","equal corrections prefer leading edge");result=TimelineSnapping.Move(0,2,1,new[]{1.0625,.9375},100,false);Check(result.Target==1.0625,"equal leading-edge ties retain stable target order");result=TimelineSnapping.Move(1,2,.875,new[]{4.0},64,false);Check(result.Target==null&&result.Delta==.875,"exact eight-display-pixel endpoint threshold does not snap");result=TimelineSnapping.Move(1,2,.876,new[]{4.0},64,false);Check(result.Target==4&&result.Delta==1,"endpoint threshold scales with view zoom");result=TimelineSnapping.Move(1,2,.96,new[]{4.0},100,true);Check(result.Delta==.96&&result.Target==null&&result.Edge==null,"bypass preserves requested movement");result=TimelineSnapping.Move(1,2,.96,new double[0],100,false);Check(result.Delta==.96&&result.Target==null,"no targets preserves requested movement");
  SnapReject(()=>TimelineSnapping.Move(double.NaN,1,0,new[]{0.0},1,false),"nonfinite move start rejected");SnapReject(()=>TimelineSnapping.Move(-1,1,0,new[]{0.0},1,false),"negative move start rejected");SnapReject(()=>TimelineSnapping.Move(0,0,0,new[]{0.0},1,false),"zero selection span rejected");SnapReject(()=>TimelineSnapping.Move(0,1,double.PositiveInfinity,new[]{0.0},1,false),"nonfinite movement rejected");SnapReject(()=>TimelineSnapping.Move(0,1,0,new[]{double.NaN},1,false),"nonfinite move target rejected");SnapReject(()=>TimelineSnapping.Move(0,1,0,new[]{0.0},0,false),"zero move zoom rejected");SnapReject(()=>TimelineSnapping.Move(0,1,0,null,1,false),"null move targets rejected");SnapReject(()=>TimelineSnapping.Move(double.MaxValue,double.MaxValue,0,new[]{0.0},1,false),"overflowing move bounds rejected");
  var p=Clone(original);p.LockedTracks.Clear();p.Clips[0].Start=1;p.Clips[0].Duration=.5;p.Clips[1].Start=3;p.Clips[1].Duration=.5;TimelineMarkers.Add(p,5);Reset(editor,p);Set(editor,"zoom",100.0);Call(editor,"Seek",6.0);var current=P(editor);var group=current.Clips.ToList();var options=(TimelineSnapOptions)Field(editor,"timelineSnapping");string baseline=json.Serialize(current);double head=(double)Field(editor,"head");
  double delta=(double)Call(editor,"SnapClipMove",1.0,1.46,group);Check(MoveNear(delta,1.5),"editor group span snaps its trailing edge to enabled marker");Check(MoveNear((double)Call(editor,"SnapClipMove",1.0,.04,group),.04),"editor excludes every moving group member from targets");current.SnapDisabledTracks.Add(0);Check(MoveNear((double)Call(editor,"SnapClipMove",1.0,1.46,group),1.46),"disabled source track bypasses endpoint snapping");current.SnapDisabledTracks.Clear();options.Markers=false;options.Playhead=false;Check(MoveNear((double)Call(editor,"SnapClipMove",1.0,1.46,group),1.46),"disabled marker and playhead targets are not used");var target=new Clip{MediaId=current.Media[2].Id,Start=5.5,Duration=.5,Track=2};current.Clips.Add(target);Check(MoveNear((double)Call(editor,"SnapClipMove",1.0,1.96,group),2),"group trailing edge uses enabled external clip edge");current.SnapDisabledTracks.Add(2);Check(MoveNear((double)Call(editor,"SnapClipMove",1.0,1.96,group),1.96),"disabled target track is excluded from endpoint snapping");current.SnapDisabledTracks.Clear();current.Clips.Remove(target);options.Markers=options.Playhead=true;Check(json.Serialize(current)==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"endpoint planning is read-only");
  Call(editor,"SetSelected",new object[]{group.ToArray()});Call(editor,"MoveSelectionTimeline",delta,0);current=P(editor);Check(MoveNear(current.Clips[0].Start,2.5)&&MoveNear(current.Clips[1].Start,4.5),"actual editor move operation applies snapped group delta");Check(MoveNear(current.Clips[1].Start-current.Clips[0].Start,2)&&current.Clips.All(c=>c.Duration==.5),"snapped group movement preserves internal gaps and durations");Check(Undos(editor)==1&&(double)Field(editor,"head")==head,"snapped editor movement has one checkpoint and preserves head");Check(current.Clips[0].MediaId==p.Clips[0].MediaId&&json.Serialize(current.Groups)==json.Serialize(p.Groups),"snapped movement retains sources and group membership");string after=json.Serialize(current);var frame=BatchPixels(preview,current,2.75);int center=(90*320+160)*4;Check(frame[center+2]>200&&frame[center]<30,"snapped movement preview shows source at new position");string video=Path.Combine(root,"move-snap.mp4"),rgb=Path.Combine(root,"move-snap.rgb");Engine.Render(current,video,null);Engine.Run("ffmpeg","-y -v error -ss 2.75 -i "+Engine.Quote(video)+" -frames:v 1 -pix_fmt rgb24 -f rawvideo "+Engine.Quote(rgb));var decoded=File.ReadAllBytes(rgb);Check(decoded[(90*320+160)*3]>200&&decoded[(90*320+160)*3+2]<30,"decoded snapped movement export agrees with preview");string file=Path.Combine(root,"move-snap.tasiaproj");Engine.Save(current,file);Check(json.Serialize(Engine.Load(file))==after,"snapped movement saves and reopens exactly");Call(editor,"Undo");Check(json.Serialize(P(editor))==baseline,"one undo restores whole pre-snap project");Call(editor,"Redo");Check(json.Serialize(P(editor))==after,"one redo restores snapped group movement");Call(editor,"Undo");current=P(editor);current.LockedTracks.Add(0);Call(editor,"SetSelected",new object[]{current.Clips.ToArray()});string locked=json.Serialize(current);Call(editor,"MoveSelectionTimeline",delta,0);Check(json.Serialize(current)==locked&&Undos(editor)==0,"snapped move retains locked-track operation guard");Reset(editor,original);
 }
}
